#[inline]
pub fn digit_sum_twice(num: u64) -> (i64, i64) {
    if num < 10 {
        return (num as i64, num as i64);
    }
    let a = digit_sum_u64(num.abs_diff(0));
    (a, if a < 10 { a } else { LOOKUP[a as usize] as i64 })
}

#[inline]
pub fn digit_sum(num: i64) -> i64 {
    if num >= 0 && num < 10 {
        return num; // super frequent case
    }
    digit_sum_u64(num.abs_diff(0))
}
#[inline]
pub fn digit_sum_u64(num: u64) -> i64 {

    #[inline]
    fn lookup(num: u64) -> u8 {
        LOOKUP[num as usize]
    }

    if num < LOOKUP_SIZE {
        return lookup(num) as i64;
    }

    let mut num = num;
    let mut sum = 0;
    while num >= LOOKUP_SIZE {
        sum += lookup(num % LOOKUP_SIZE);
        num /= LOOKUP_SIZE;
    }
    sum += lookup(num);
    sum as i64
}

pub fn digit_sum_range(r: RangeInclusive<i64>) -> RangeInclusive<i64> {
    digit_sum_range_u64(abs_range(r))
}
pub fn digit_sum_range_u64(r: RangeInclusive<u64>) -> RangeInclusive<i64> {
    let (lo, hi) = r.into_inner();
    assert!(lo <= hi);
    if lo == hi {
        let ds = digit_sum_u64(lo);
        return ds..=ds;
    }

    let lo_str = lo.to_string();
    let hi_str = hi.to_string();
    let lo_str = "0".repeat(hi_str.len() - lo_str.len()) + &lo_str;
    debug_assert_eq!(lo_str.len(), hi_str.len());

    let mut olo = 0;
    let mut ohi = 0;
    let mut common_part = -1;
    for (i, (lc, hc)) in lo_str.chars().zip(hi_str.chars()).enumerate() {
        ohi = ohi * 10 + hc.to_digit(10).unwrap() as u64;
        olo = olo * 10 + lc.to_digit(10).unwrap() as u64;

        if lc != hc {
            common_part = i as i32;
            break;
        }
    }
    assert!(common_part >= 0);

    ohi -= 1;
    olo += 1;
    for _ in common_part + 1..(lo_str.len() as i32) {
        ohi = ohi * 10 + 9;
        olo = olo * 10 + 0;
    }

    // println!("digit_sum_range({r:?}) -> cs({olo})..=cs({ohi})");

    assert!(olo <= hi && olo >= lo && ohi >= lo && ohi <= hi, "out of range input: {}..={}, olo={}, ohi={}", lo, hi, olo, ohi);

    cmp::min(digit_sum_u64(olo), digit_sum_u64(lo))..=cmp::max(digit_sum_u64(ohi), digit_sum_u64(hi))
}

/// Finds the largest number in r which has the digit_sum = target_ds
pub fn digit_sum_find_in_range(r: RangeInclusive<u64>, target_ds: i64) -> Option<u64> {
    let (lo, hi) = r.clone().into_inner();
    assert!(hi <= i64::MIN.unsigned_abs());
    assert!(lo <= hi);

    let lo_str = lo.to_string();
    let hi_str = hi.to_string().chars().map(|c| c.to_digit(10).unwrap() as u8).collect::<Vec<u8>>();
    let lo_str = "0".repeat(hi_str.len() - lo_str.len()) + &lo_str;
    let lo_str = lo_str.chars().map(|c| c.to_digit(10).unwrap() as u8).collect::<Vec<u8>>();

    debug_assert_eq!(lo_str.len(), hi_str.len());

    let mut common_prefix = 0;
    let mut common_size = None;
    for (i, (&ld, &hd)) in lo_str.iter().zip(hi_str.iter()).enumerate() {
        if ld == hd {
            common_prefix = common_prefix * 10 + (hd as u64);
        } else {
            common_size = Some(i);
            break;
        }
    }
    let Some(common_size) = common_size else {
        assert_eq!(lo, hi);
        return (digit_sum_u64(lo) == target_ds).then_some(lo);
    };

    debug_assert_ne!(0, hi_str[common_size]);
    debug_assert_ne!(9, lo_str[common_size]);

    let common_sum = digit_sum_u64(common_prefix);
    if common_sum + lo_str[common_size] as i64 == target_ds {
        // ok now only way to save this is if lo_str ends with all zeros
        //    <==> CS(lo) == target_ds
        // no higher answer exists
        return (digit_sum_u64(lo) == target_ds).then_some(lo);
    }
    if common_sum + lo_str[common_size] as i64 > target_ds {
        return None
    }
    // now it should always be within reach from lower bound

    if common_sum + hi_str[common_size] as i64 >= target_ds {
        // we cannot use highest digit, so let's use the max we can + pad with zeros
        let digit = target_ds - common_sum;
        debug_assert!(digit >= 0);
        return Some((common_prefix * 10 + digit as u64) * 10u64.pow((lo_str.len() - common_size - 1) as u32));
    }

    // we copy hi until we reach target_ds, then pad with zeros
    let mut optimistic = common_prefix * 10 + hi_str[common_size] as u64;
    let mut optimistic_sum = common_sum + hi_str[common_size] as i64;
    // we put 9 until we reach target_ds
    let mut pesimistic = optimistic - 1;
    let mut pesimistic_sum = optimistic_sum - 1;

    // println!("DBG {optimistic} {optimistic_sum} {pesimistic} {pesimistic_sum}");

    let mut pesimistic_size = common_size + 1;
    for ix in (common_size + 1)..lo_str.len() {
        let digit = hi_str[ix];

        if optimistic_sum + digit as i64 >= target_ds {
            let dg = target_ds - optimistic_sum;
            assert!(dg > 0 && dg <= 9);
            return Some((optimistic * 10 + dg as u64) * 10u64.pow((lo_str.len() - ix - 1) as u32));
        }

        let remaining_len = (lo_str.len() - ix) as i64;

        // println!("DBG optimistic {optimistic} sum={optimistic_sum} digit={digit} target_ds={target_ds} (pesimist can reach {})", optimistic_sum - 1 + remaining_len * 9);
        if optimistic % 10 > 0 && optimistic_sum - 1 + remaining_len * 9 >= target_ds {
            // pesimist has a chance from here
            pesimistic_size = ix;
            pesimistic = optimistic - 1;
            pesimistic_sum = optimistic_sum - 1;
        }

        optimistic = optimistic * 10 + digit as u64;
        optimistic_sum += digit as i64;
    }

    for ix in pesimistic_size..lo_str.len() {
        // println!("DBG pesimistic {pesimistic} sum={pesimistic_sum}  target_ds={target_ds}");
        if pesimistic_sum + 9 >= target_ds {
            let dg = target_ds - pesimistic_sum;
            assert!(dg > 0 && dg <= 9);
            let result = (pesimistic * 10 + dg as u64) * 10u64.pow((lo_str.len() - ix - 1) as u32);
            debug_assert_eq!(target_ds, digit_sum_u64(result), "Invalid result for {r:?}: result={result}");
            return Some(result);
        }

        pesimistic = pesimistic * 10 + 9;
        pesimistic_sum += 9;
    }

    debug_assert!(target_ds > *digit_sum_range_u64(r.clone()).end(), "WTF, why didn't we find it? {r:?} {target_ds} optimistic={optimistic} pesimistic={pesimistic}");

    None
}

// fn digit_sum_find_in_range_signed(a: i64, a: i64)

pub struct DigitSumInverseIterator {
    range: RangeInclusive<u64>,
    target_ds: i64,
}

impl DigitSumInverseIterator {
    pub fn new(range: RangeInclusive<u64>, target_ds: i64) -> Self {
        assert!(target_ds > 0, "invalid target_ds={target_ds}"); // zero not allowed, it is trivial
        Self { range, target_ds }
    }
}

impl Iterator for DigitSumInverseIterator {
    type Item = u64;
    fn next(&mut self) -> Option<Self::Item> {
        if self.range.start() > self.range.end() {
            None
        }
        else if let Some(next) = digit_sum_find_in_range(self.range.clone(), self.target_ds) {
            self.range = *self.range.start() ..= (next - 1);
            Some(next)
        }
        else {
            self.range = 1..=0;
            None
        }
    }
}

pub fn evaluate_constant_propagation_feasibility(range: RangeInclusive<i64>, constant: i64, max_output: usize) -> Option<Vec<i64>> {
    let mut result = vec![];
    for val in DigitSumInverseIterator::new(abs_range(&range), constant) {
        if val == i64::MIN.unsigned_abs() {
            result.push(i64::MIN)
        } else {
            let v = val as i64;
            if range.contains(&v) {
                result.push(v);
            }
            if range.contains(&-v) {
                result.push(-v);
            }
        }
        if result.len() > max_output {
            return None
        }
    }
    Some(result)
}

pub fn digit_sum_reference(num: i64) -> i64 {
    let num = num.abs_diff(0);
    let mut num = num;
    let mut sum = 0;
    while num > 0 {
        sum += num % 10;
        num /= 10;
    }
    sum as i64
}

#[test]
fn test_digit_sum() {
    for i in -300..20_000 {
        assert_eq!(digit_sum(i), digit_sum_reference(i));
    }
}

#[test]
fn test_digit_sum_examples() {
    for i in [i64::MIN, -8999999999999999999, 8999999999999999999, 9199999999999999999, i64::MAX] {
        assert_eq!(digit_sum(i), digit_sum_reference(i));
    }
}

#[test]
fn test_digit_range() {
    assert_eq!(0..=9, digit_sum_range(0..=9));
    assert_eq!(0..=9, digit_sum_range(-9..=15));
    assert_eq!(0..=18, digit_sum_range(-13..=130));
    assert_eq!(0..=18, digit_sum_range(-130..=13));
    assert_eq!(2..=11, digit_sum_range(100001..=100020));
    assert_eq!(2..=11, digit_sum_range(100001..=100019));
    assert_eq!(2..=10, digit_sum_range(100001..=100018));
    assert_eq!(2..=29, digit_sum_range(10000100..=10002000));
    assert_eq!(2..=29, digit_sum_range(10000200..=10002000));
    assert_eq!(170, digit_sum(8999999999999999999));
    assert_eq!(0..=170, digit_sum_range(-i64::MAX..=i64::MAX));
    assert_eq!(0..=170, digit_sum_range(0..=i64::MAX));
    assert_eq!(1..=170, digit_sum_range(1..=i64::MAX));
    assert_eq!(1..=18, digit_sum_range(1..=170));
    assert_eq!(1..=16, digit_sum_range(100..=170));
    assert_eq!(1..=16, digit_sum_range(100..=169));
    assert_eq!(3..=15, digit_sum_range(120..=168));
    for i in [i64::MIN, -8999999999999999999, 8999999999999999999, 9199999999999999999, i64::MAX] {
        assert_eq!(digit_sum(i), digit_sum_reference(i));
    }
}

#[test]
fn test_digit_range_find() {
    use rustc_hash::{FxHashMap as HashMap};
    assert_eq!(vec![45, 36, 27, 18, 9], DigitSumInverseIterator::new(0..=50, 9).collect::<Vec<u64>>());
    assert_eq!(vec![8999999999999999999], DigitSumInverseIterator::new(0..=i64::MIN.unsigned_abs(), 170).collect::<Vec<u64>>());
    assert_eq!(None, digit_sum_find_in_range(0..=8999999999999999997, 171));
    assert_eq!(Some(8999999999999999989), digit_sum_find_in_range(8999999999999999900..=8999999999999999997, 169));
    assert_eq!(Some(13), digit_sum_find_in_range(10..=19, 4));
    assert_eq!(Some(11002), digit_sum_find_in_range(10000..=11009, 4));
    assert_eq!(Some(8999999999999999989), digit_sum_find_in_range(0..=8999999999999999997, 169));
    assert_eq!(vec![8999999999999999998, 8999999999999999989, 8999999999999999899, 8999999999999998999, 8999999999999989999, 8999999999999899999, 8999999999998999999, 8999999999989999999, 8999999999899999999, 8999999998999999999, 8999999989999999999, 8999999899999999999, 8999998999999999999, 8999989999999999999, 8999899999999999999, 8998999999999999999, 8989999999999999999, 8899999999999999999, 7999999999999999999], DigitSumInverseIterator::new(0..=i64::MIN.unsigned_abs(), 169).collect::<Vec<u64>>());
    assert_eq!(vec![1000000000000000000, 100000000000000000, 10000000000000000, 1000000000000000, 100000000000000, 10000000000000, 1000000000000, 100000000000, 10000000000, 1000000000, 100000000, 10000000, 1000000, 100000, 10000, 1000, 100, 10, 1], DigitSumInverseIterator::new(0..=i64::MIN.unsigned_abs(), 1).collect::<Vec<u64>>());
    assert_eq!(0, DigitSumInverseIterator::new(120000..=121009, 2).count());
    assert_eq!(vec![120000], DigitSumInverseIterator::new(120000..=121009, 3).collect::<Vec<_>>());
    assert_eq!(Some(120910), digit_sum_find_in_range(120000..=121008, 13));
    assert_eq!(Some(120300), digit_sum_find_in_range(120000..=121001, 6));

    let mut groups: HashMap<i64, Vec<u64>> = HashMap::default();
    for x in (120000..=121009).rev() {
        groups.entry(digit_sum_u64(x)).or_default().push(x);
    }
    let empty_vec = vec![];
    for sum in 1..40 {
        assert_eq!(
            groups.get(&sum).unwrap_or_else(|| &empty_vec),
            &DigitSumInverseIterator::new(120000..=121009, sum).collect::<Vec<_>>(),
            "Test failed for sum={sum}"
        );
    }
}
